import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  // Root group for this node
  const root = new ctx.THREE.Group();

  // Plane geometry (unit size, can be scaled via config.scale if needed)
  const geometry = new ctx.THREE.PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ toneMapped: true });
  const plane = new ctx.THREE.Mesh(geometry, material);
  plane.position.set(-3.2, 1, 0.06);
  root.add(plane);

  // Track disposable resources
  const disposableTextures = [];
  const disposableTimelines = [];
  const disposablePrimitives = [];

  // Load texture (if provided)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      disposableTextures.push(tex);
    });
  }

  // Create and add text objects
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config?.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Slightly offset in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Apply cinematic primitives (if any)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const p = ctx.primitives[prim.name](root, prim.params);
      disposablePrimitives.push(p);
    }
  }

  // Event handlers container (none for this spec)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    disposableTimelines.forEach((t) => t.kill());

    // Cleanup primitives
    disposablePrimitives.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });

    // Dispose material, geometry, and textures
    material.dispose();
    geometry.dispose();
    disposableTextures.forEach((t) => t.dispose());

    // Dispose any additional meshes added (e.g., text)
    root.traverse((child) => {
      if (child.isMesh && child !== plane) {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      }
    });
  };

  return root;
}
